import { EventEmitter } from 'node:events';
function main(): void {
  const e: any = new EventEmitter();
  const f = () => {};
  const k: any = e.on('b', f).on('c', f);
  console.log(typeof k, k === e, k.listenerCount('c'));
  const j: any = e.on('b', f).on('c', f).on('d', f);
  console.log(j === e, j.listenerCount('d'));
  k.marker = 5;
  console.log(e.marker);
}
